package com.xiuxian.script;

import android.content.Context;
import android.util.Base64;

import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

/**
 * 天途分步流程的内置资源包：
 *   识别模板（tpl/*.png，已转成运行时用的灰度）+ 各任务流程（flows/*.json）。
 * 以 base64 的 zip 内嵌在代码里，首次运行时解到 App 私有目录（tpl/ 与 flows/）。
 */
public final class BundledFlows {

    private static final String[] CHUNKS = {
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
    };

    private BundledFlows() {
    }

    /** 解包到 filesDir/flowpack，已解过就直接返回 */
    public static synchronized File ensure(Context ctx) {
        File root = ctx.getFilesDir();
        File mark = new File(root, ".flowpack_ok");
        if (mark.exists()) {
            return root;
        }
        try {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < CHUNKS.length; i++) {
                sb.append(CHUNKS[i]);
            }
            byte[] zip = Base64.decode(sb.toString(), Base64.DEFAULT);
            ZipInputStream zin = new ZipInputStream(new ByteArrayInputStream(zip));
            byte[] buf = new byte[8192];
            ZipEntry e;
            while ((e = zin.getNextEntry()) != null) {
                File out = new File(root, e.getName());
                File dir = out.getParentFile();
                if (dir != null && !dir.exists()) {
                    dir.mkdirs();
                }
                FileOutputStream os = new FileOutputStream(out);
                int n;
                while ((n = zin.read(buf)) > 0) {
                    os.write(buf, 0, n);
                }
                os.close();
                zin.closeEntry();
            }
            zin.close();
            mark.createNewFile();
        } catch (Throwable t) {
            // 解包失败就下次重试
        }
        return root;
    }

    /** 某个流程的 json 文本 */
    public static String flowText(Context ctx, String name) {
        File f = new File(new File(ensure(ctx), "flows"), name);
        if (!f.exists()) {
            return null;
        }
        try {
            InputStream in = new java.io.FileInputStream(f);
            java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int n;
            while ((n = in.read(buf)) > 0) {
                bos.write(buf, 0, n);
            }
            in.close();
            return new String(bos.toByteArray(), "UTF-8");
        } catch (Throwable t) {
            return null;
        }
    }

    /** 全部流程文件名 */
    public static String[] flowNames(Context ctx) {
        File dir = new File(ensure(ctx), "flows");
        String[] l = dir.list();
        return l == null ? new String[0] : l;
    }
}
